A: You can use the following code:
import re

def count_letters(string):
    return len(re.findall(r'[a-z]', string))

def list_letters(string):
    return [x for x in string if x.isalpha()]

def main():
    string = input('Enter a string: ')
    print(count_letters(string))
    print(list_letters(string))

if __name__ == '__main__':
    main()

